import json
def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for r in grid for x in r).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # collect diagonal lines: key=(slope, offset), all same color, len>=2 or single
    lines={}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg: continue
            for slope,key in ((1,('s1',c-r)),(-1,('s-1',c+r))):
                lines.setdefault(key,{}).setdefault(v,[]).append((r,c))
    # for each (key,color) with cells, draw full line
    for key,bycol in lines.items():
        for v,pts in bycol.items():
            r0,c0=pts[0]
            for r in range(h):
                c = c0+(r-r0) if key[0]=='s1' else c0-(r-r0)
                if 0<=c<w: out[r][c]=v
    return out

