import re,json
def parse(text):
    # extract demo pairs N input/output
    pairs={}
    for m in re.finditer(r'Demo pair (\d+) (input|output) \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)', text):
        n,kind,R,C,body=int(m.group(1)),m.group(2),int(m.group(3)),int(m.group(4)),m.group(5)
        rows=[[int(x) for x in r.split()] for r in body.strip().split('\n')]
        assert len(rows)==R and all(len(r)==C for r in rows), (n,kind,len(rows))
        pairs.setdefault(n,{})[kind]=rows
    return pairs
