    others={(r,c) for cl in by.values() for r,c in cl}
    draws=[]
    for v,cl in by.items():
        cs=set(cl)
        for dr,dc in ((1,1),(1,-1)):
            for r,c in cl:
                if (r-dr,c-dc) not in cs: continue
                # not start; only process starts
                continue
            for r,c in cl:
                if (r-dr,c-dc) in cs: continue
                run=[]; rr,cc=r,c
                while (rr,cc) in cs: run.append((rr,cc)); rr+=dr; cc+=dc
                if len(run)<2: continue
                (r0,c0),(r1,c1)=run[0],run[-1]
                # continuation check at each end
                def cont(e, dr2,dc2):
                    rr2,cc2=e[0]+dr2,e[1]+dc2
                    return 0<=rr2<R and 0<=cc2<C and (rr2,cc2) in others and g[rr2][cc2]!=bg and (rr2,cc2) not in cs
                ends=[((r0,c0),(-dr,-dc),cont((r0,c0),-dr,-dc)), ((r1,c1),(dr,dc),cont((r1,c1),dr,dc))]
                for e,d,has_c in ends:
                    if len(run)>=3 or (len(run)==2 and any(h for _,_,h in ends)):
                        pass
                    else:
                        continue
                    # extend from e in dir d if allowed: len>=3 always; len==2 only away from continuation
                    if len(run)==2:
                        # extend only from the end whose outward dir points AWAY from the continuation cell
                        cont_end = ends[0] if ends[0][2] else (ends[1] if ends[1][2] else None)
                        if cont_end is None: continue
                        # away = from the opposite end
                        if (e,d)==(cont_end[0],cont_end[1]): continue
                    rr,cc=e[0]+d[0],e[1]+d[1]
                    while 0<=rr<R and 0<=cc<C and (rr,cc) not in others and g[rr][cc]==bg:
                        draws.append((rr,cc,v)); rr+=d[0]; cc+=d[1]
    for r,c,v in draws: g[r][c]=v
    return g

